local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["07008d843c1f0118"] = { "Ti sembra che io lanci incantesimi? Beh, ho sentito che Cain Firesong bazzicava il pianerottolo al piano di sopra della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, all'estremità sud-est della città. Strano come se ne stia lì, fuori dalla stanza di Gretchen.", "." },
  ["0709ec00a8f8c254"] = { "Niente ci fermerà! Morirai!", "." },
  ["07208e92bc7102f5"] = { "Non sei <un/una> <druido/druida>!", "." },
  ["072309b207ba57ed"] = { "Ne esistono altri mille come lui. Diecimila. Se uno cade, un altro sorgerà a prendere il seggio del potere.", "." },
  ["07272c3405913efb"] = { "Uff! Che giornataccia per pescare sarà questa. Ah, pazienza: una brutta giornata di pesca è sempre meglio di una bella giornata di lavoro.", "." },
  ["07283a656a8cfe2f"] = { "Andiamo prima che scoprano che sono in libertà!", "." },
  ["072ca22c0875838e"] = { "Beh, ora o mai più, suppongo. Ricorda, una volta raggiunta la strada sani e salvi, torna da Terenthis per fargli sapere che siamo scappati.", "." },
  ["072df3d5ba189d59"] = { "Non dobbiamo arrenderci!", "." },
  ["073525993b8ff144"] = { "Combatti!", "." },
  ["073b5ab1ca115af9"] = { "Il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo conquisterà!", "." },
  ["0740cbda3c68b4d8"] = { "Se hai il fegato di sorbirti racconti che ti faranno tremare il fasciame e inzuppare le mutande, prenditi da bere e siediti un momento...", "." },
  ["07451e2e3c85e258"] = { "Salve, <signore/signora>... hai un po' di tempo per darci una mano? Per favore?", "." },
  ["0749090f64f1496a"] = { "Trovi il maestro dei grifoni sul bastione nord-est che domina la ⟦Valley of Heroes=Valle degli Eroi⟧.", "." },
  ["07497adafba49341"] = { "Mi sembra morto. Così non ci serve a molto. Faresti meglio a tornare a dire a Krog cos'è successo.", "." },
  ["074e479d4e67c096"] = { "Bevande gustose in vendita! Placa la sete con le migliori birre della Fiera di Lunacupa!", "." },
  ["074e6a785061032f"] = { "Se sei qui per imparare le tattiche e le strategie della caccia, sei nel posto giusto!", "." },
  ["07512594f71c7a72"] = { "%s accorre in aiuto di Feugen!", "." },
  ["0761b2cb591f5034"] = { "Dove sono finite le tue buone maniere, fratello? Diamo ai nostri ospiti il benvenuto che meritano.", "." },
  ["076340e59a57e69d"] = { "La stoffa va bene. Personalmente, preferisco lavorare la pelle umana.", "." },
  ["0764263620a3657d"] = { "Il metallo, come ogni cosa, va usato in equilibrio con la natura. Karn Stonehoof ha una fucina vicino allo stagno, sull'altura inferiore. Cerca la sua saggezza.", "." },
  ["0769ef3d4a261e75"] = { "Salute, {class}! Ti do il benvenuto alla festa!", "." },
  ["07763c5b2326f7f9"] = { "L'aria vibra di energia, Arcidruido. Come sta il Signore della Foresta?", "." },
  ["07894e7228418da8"] = { "Giornata storta? Prova un po' di torta di ciliegie.", "." },
  ["078d085a8b5b3221"] = { "Ho pescato un pesce, se hai fame...", "." },
  ["079023dd5e954503"] = { "Lavoro per la città, all'ufficio del censimento di Sepulcra. Da quando ci siamo liberati dal Flagello, cerchiamo di tenere un registro accurato della popolazione della città. Grazie a metodi arcani e a una disciplina mentale affinata, posso accedere a questi registri. Se hai affari da sbrigare con me in tal senso, procedi pure. Del resto, se ne hai, dovresti saperlo.", "." },
  ["0790819de82e15c4"] = { "Questi alberi sono davvero magnifici, non trovi?", "." },
  ["0791aec9a33a2a25"] = { "Ho perso la mia ⟦Blade of Eternal Justice=Lama dell'Eterna Giustizia⟧. Puoi sostituirmela?", "." },
  ["0792b0d44d6aa012"] = { "Cosa posso fare per te, <compagno/compagna> windshaper?", "." },
  ["07933ece98940286"] = { "Ce l'abbiamo fatta! Grazie ancora! Io corro avanti!", "." },
  ["079aa4829122850c"] = { "Di nuovo qui per imparare, {name}? Vieni qui e mostrami che sei <pronto/pronta>.", "." },
  ["07a1595f0fc2658b"] = { "Siamo sopravvissuti!", "." },
  ["07a90bbcbf747c01"] = { "Karn dice che dobbiamo ascoltare gli spiriti della forgia e dell'acciaio, che ci guideranno. Io sento solo un fischio nelle orecchie. Ecco, prendi un martello e proviamo ad ascoltare gli spiriti insieme.", "." },
  ["07b0d88463da0a82"] = { "%s sussurra qualcosa all'orecchio di {name}.", "." },
  ["07b1d6a00b6a21a0"] = { "Gli umani e la loro cosiddetta Lega di Arathor pensano di cacciarci dal ⟦Arathi Basin=Bacino d'Arathi⟧. Non credo proprio, {class}! Sei <pronto/pronta> a partire per dimostrare che sono loro, e non i ⟦The Defilers=Profanatori⟧, a doversene andare presto?", "." },
  ["07c30290c6904999"] = { "Meno male che qui qualcuno sa seguire le tracce! Cerca Shim'la nella Hunter's Hall, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["07cb9773f20b842d"] = { "<Eris annuisce.>\n\nL'Occhio ha visto tanti orrori e tante meraviglie.\n\nMostra ciò che ritiene più adatto da vedere per chi vi guarda dentro.", "." },
  ["07cd8f94ec9e871f"] = { "Parlami del ⟦Warlords Deck=Mazzo dei Signori della Guerra⟧.", "." },
  ["07d42302a0bcbb3a"] = { "Quale patto?", "." },
  ["07d961fc076e17c2"] = { "Mare in burrasca là fuori. Gli spiriti del mare devono essere inquieti....hic!", "." },
  ["07e388b086ca548d"] = { "Gli ordini sono stati dati! Morte ai Piccatonante! Caricate il nemico!", "." },
  ["07e4ecfe3ca681f6"] = { "Signore, allievo chiede di essere bastonato per sua scarsa comprensione!", "." },
  ["07e94c154dcd51f2"] = { "Puoi affidare tranquillamente i tuoi famigli alle cure di Alassin. Risiede nell'⟦Cenarion Enclave=Enclave Cenariana⟧, dove si radunano i cacciatori.", "." },
  ["07f1dcd959daa47d"] = { "Bene, allora. A parte le ovvie distrazioni che una servitrice come questa offrirà contro i tuoi nemici più virili, è anche capace di infliggere quantità di danni notevoli. Tuttavia, la sua fragile resistenza la rende quasi inutile come scudo.", "." },
  ["07f37aac3d3aa849"] = { "Niente di meglio che passare una giornata a pescare al ⟦Crystal Lake=Lago di Cristallo⟧. È Arnold Leland che mi ha insegnato. Di solito lo trovi sul molo del Canal District, a pescare tutto il giorno.\n\nAh, e non credere a nessuna delle storie che ti racconta sui mostri nei canali.", "." },
  ["07f941e268c541d5"] = { "In questo cerchio di fuoco devo lanciare l'incantesimo per bandire gli spiriti dei Fanglord uccisi.", "." },
  ["07f985ef60d66b5c"] = { "Buongiorno, <ragazzo/ragazza>! Forse potresti aiutarmi con alcune faccende da sbrigare.", "." },
  ["07fa5e07e525fcad"] = { "L'incantesimo di guarigione è fallito. Purtroppo, l'introduzione del siero nel sangue di questa bestia porrà presto fine alla sua vita.", "." },
  ["07ff5b4fd5eefd94"] = { "Sarà fatto, Eranikus. Sta' bene, antico.", "." },
})
